import{_ as a,c as n,a as d,o as r}from"./app-BJ-EBxz8.js";const c={};function i(p,e){return r(),n("div",null,e[0]||(e[0]=[d('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-10-21-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-10-21-资讯日报"><span>2026-10-21 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="claude-64小时设计出抗致命蝎毒蛋白" tabindex="-1"><a class="header-anchor" href="#claude-64小时设计出抗致命蝎毒蛋白"><span>Claude 64小时设计出抗致命蝎毒蛋白</span></a></h3><p>Anthropic：Claude仅用64小时自主设计出抗致命蝎毒结合蛋白，湿实验验证17个设计成功达标，多靶点设计暂未突破，全部数据已开源，为AI药物研发开辟新方向。<a href="https://mp.weixin.qq.com/s?__biz=Mzg3MTkxMjYzOA==&amp;chksm=cfe024aace30f87bafc2df6604bb23d78b9b09f7a7a20e9ff4cde177943442df8abbb802f718&amp;idx=2&amp;mid=2247519733&amp;sn=b924c295dc0734d7229a83f515e1b19d#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="anthropic估值砍5000亿-半年巨亏807亿" tabindex="-1"><a class="header-anchor" href="#anthropic估值砍5000亿-半年巨亏807亿"><span>Anthropic估值砍5000亿 半年巨亏807亿</span></a></h3><p>Anthropic最新招股书披露，上半年营收暴增14倍达163亿美元，但净亏807亿美元，未来锁定超7500亿不可撤销算力支出，投资者下调其上市估值5000亿，暴露大模型增长隐忧。<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=fa143d3df071e6d7aa0b72ce576ece97d39589b18350cdc9084f59506ed0c0948210d7f6cd57&amp;idx=1&amp;mid=2247668681&amp;sn=8bc5e89bb424c0dae6bdb0a509816525#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="陶哲轩邓煜呼吁数学「慢科研」" tabindex="-1"><a class="header-anchor" href="#陶哲轩邓煜呼吁数学「慢科研」"><span>陶哲轩邓煜呼吁数学「慢科研」</span></a></h3><p>陶哲轩、邓煜：AI可承担繁琐推导、带来新想法，但AI解出问题不代表人类理解证明，呼吁保留慢科研价值增进理解，推动开放数学工具开发，让AI真正服务数学研究。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9efbef1cb6b16936c28076932d9236edb72225bd8c2e954693a2c95bc3542cbe7c47e4d2905&amp;idx=1&amp;mid=2247935057&amp;sn=fe3f30ca8005f7b5422d8e2c83632804#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="claude首次设计出抗蝎毒蛋白" tabindex="-1"><a class="header-anchor" href="#claude首次设计出抗蝎毒蛋白"><span>Claude首次设计出抗蝎毒蛋白</span></a></h3><p>Anthropic：内部研究版Claude协助非专业团队设计出抗蝎毒结合蛋白，17种通过实测，数据已公开，展示了AI在冷门药物研发领域的巨大潜力。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0aad1b5519f74c84f11dd7816d8675932eba6cf2f567d3c3511ffcdd31fe8fde56541afcc92&amp;idx=1&amp;mid=2652736457&amp;sn=7ac7c86fbd43cb906b4be218dcdd98d1#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="meta叫停裁员-称还是人类好用" tabindex="-1"><a class="header-anchor" href="#meta叫停裁员-称还是人类好用"><span>Meta叫停裁员，称还是人类好用</span></a></h3><p>Meta原定裁员用AI替代人类，结果AI效率不升事故反增，紧急叫停第二轮裁员；微软发现推广AI后业务未达标，开始削减AI预算，AI员工泡沫开始破裂。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9460bb078d82b4ae80da374ceceaeaf91ad3b70da82375d4156b525bec957321e8985b44b6a&amp;idx=2&amp;mid=2247935057&amp;sn=4326615801eaca067616f3e007ed820d#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai将cobol迁移准确率提至97-9" tabindex="-1"><a class="header-anchor" href="#openai将cobol迁移准确率提至97-9"><span>OpenAI将COBOL迁移准确率提至97.9%</span></a></h3><p>OpenAI最新研究显示，COBOL代码迁移准确率从5.4%提升到97.9%，AI编程能力已拓展到低资源编程语言领域，可帮助企业迁移遗留系统，但仍需人工验证和完善工程体系保障安全。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bcb3cd06177c6934814adb02f36f5872ab2c1bdbadc91035368763819c5f8ad26b1acd881b7b&amp;idx=1&amp;mid=2651295538&amp;sn=7ce55394b23b1500735fb3f5934812e7#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="奥特曼曝超级ai三大终局" tabindex="-1"><a class="header-anchor" href="#奥特曼曝超级ai三大终局"><span>奥特曼曝超级AI三大终局</span></a></h3><p>奥特曼提出AI发展三大终局：一是成立类似国际原子能机构的监管组织，二是头部AI公司合并统一研发，三是一家率先造出可自我改进AI后熔掉别家GPU，OpenAI一年内将选定方向。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f08065aff8b2c9a484990bd47490a34ed2648d6170cc51b01409db18e1f7459ec7abc2ffa85f&amp;idx=2&amp;mid=2652736457&amp;sn=6c4a936d87f9bb32366bf3750bea19c3#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="清华团队用ai造世界最轻1克介观显微镜" tabindex="-1"><a class="header-anchor" href="#清华团队用ai造世界最轻1克介观显微镜"><span>清华团队用AI造世界最轻1克介观显微镜</span></a></h3><p>清华团队研发出全球最轻1克无线介观显微镜Airscope，成本不到700元，可在小鼠自由活动时同步记录数千个神经元，已完全开源供研究使用<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=86c08556036b0376029e8fe1a4a026ce34b1f83ec493d6de827e7d59243461ff1e0ec6cd8d89&amp;idx=1&amp;mid=2649807323&amp;sn=c8526bc8d35ec6e1145b340a164930f2#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="_2026年-我这样用ai知识库" tabindex="-1"><a class="header-anchor" href="#_2026年-我这样用ai知识库"><span>2026年，我这样用AI知识库</span></a></h3><p>黄益贺将知识库分为自用、供他人使用两类：自用靠Obsidian原生检索加Wiki结构化，放弃传统RAG；供他人使用的内容通过RAG+MCP开放给会员Agent调用，核心是积累握在自己手里<a href="https://mp.weixin.qq.com/s?__biz=MzkyNzU0MzQwOQ==&amp;chksm=c3ed2fccbf807c97293eb7ea1fea181a54ec8884233557b9cb2fa03ec1c7570f40e3c764bbc2&amp;idx=1&amp;mid=2247485545&amp;sn=0597df1005686de8ea4f30e96a6646e7#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="《2026ai原生基础设施白皮书》发布" tabindex="-1"><a class="header-anchor" href="#《2026ai原生基础设施白皮书》发布"><span>《2026AI原生基础设施白皮书》发布</span></a></h3><p>甲子光年智库与蓝耘科技：AI已进入以Agent为核心的新阶段，Token成为核心生产要素，AI原生基础设施需从单纯供给算力转向围绕Token产效组织全链路资源，支撑AI落地创造业务价值。<a href="https://mp.weixin.qq.com/s?__biz=MzU5OTI0NTc3Mg==&amp;chksm=ffcdacda8f5d07dbd47f337b13d0db96232fbb61c06adec1b05cc57681fa8332396eeb2a6366&amp;idx=1&amp;mid=2247559364&amp;sn=e76d5878fb925e0ec3318c432ca945ec#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="_1-3k-star开源项目抓ai热词快人一步" tabindex="-1"><a class="header-anchor" href="#_1-3k-star开源项目抓ai热词快人一步"><span>1.3K Star开源项目抓AI热词快人一步</span></a></h3><p>开源星探：传统关键词工具要两三周才能收录新兴AI热词，存在巨大信息差机会；开源项目new-term-radar靠八路信号当天抓热词，帮从业者提前抢占流量窗口。<a href="https://mp.weixin.qq.com/s?__biz=MzkwMjQ0NzI0OQ==&amp;chksm=c1a0a9ffcae595f828d8bf55ccc619b8a2ccc588fb2868f16704b7f21aceb59717561687e26a&amp;idx=1&amp;mid=2247507200&amp;sn=7af7ee924a3850ca7daa7dd168f608da#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="deepseek开源deepinfer推理框架" tabindex="-1"><a class="header-anchor" href="#deepseek开源deepinfer推理框架"><span>DeepSeek开源DeepInfer推理框架</span></a></h3><p>DeepSeek开源了支撑自家大模型的大规模云服务推理框架DeepInfer，首次公开推理服务层部分工程实现，配套开源协议转换组件，方便开发者学习，但完整在线能力仍未全部开放。<a href="https://mp.weixin.qq.com/s?__biz=Mzg3Mzg5MjY3Nw==&amp;chksm=cf8c70c769cb00e55f18875d290c61c06d79538fa561332742460d6d346317bed1cdcbc1e553&amp;idx=1&amp;mid=2247527186&amp;sn=f2d9e46e949d7ea7947f81bad06e3eef#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="deepseek推理利润率高达80" tabindex="-1"><a class="header-anchor" href="#deepseek推理利润率高达80"><span>DeepSeek推理利润率高达80%</span></a></h3><p>DeepSeek开源大规模推理框架，单集群日吞吐达155万亿Tokens，通过多项极致优化，在低价API下仍保持高达80%的毛利率，揭开大模型推理盈利真相。<a href="https://mp.weixin.qq.com/s?__biz=Mzg3MTkxMjYzOA==&amp;chksm=cf2637e7d947de8b9d0fc964adb86f3e5557e6b7cfd2d0017abd1c59ab8b989aa8328b7da15b&amp;idx=1&amp;mid=2247519733&amp;sn=44673515d70d2df4fa5d455c5256c403#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="rsigame让ai自主开发超gpt-5-5" tabindex="-1"><a class="header-anchor" href="#rsigame让ai自主开发超gpt-5-5"><span>RSIGame让AI自主开发超GPT-5.5</span></a></h3><p>UCSD、字节跳动与卡内基梅隆大学团队提出RSIGame框架，靠双层闭环实现AI自主试玩、修复、迭代游戏，开发经验反训模型后，27B模型配合RSIGame生成的游戏质量超过GPT-5.5一次性生成结果。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=8516d09670935fb7482861bde1be2b77c6ff4a471701c9b2df46334397617a6f5a608a358744&amp;idx=2&amp;mid=2651068740&amp;sn=71f6d8dd9b7e68abab1a1327ab0c4f6b#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',37)]))}const s=a(c,[["render",i]]),l=JSON.parse('{"path":"/posts/2026-10-21.html","title":"AI日报：Claude 64小时设计出抗致命蝎毒蛋白; Anthropic估值砍5000亿 半年巨亏807亿; 陶哲轩邓煜呼吁数学「慢科研」","lang":"zh-CN","frontmatter":{"date":"2026-10-21T00:00:00.000Z","title":"AI日报：Claude 64小时设计出抗致命蝎毒蛋白; Anthropic估值砍5000亿 半年巨亏807亿; 陶哲轩邓煜呼吁数学「慢科研」"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"Claude 64小时设计出抗致命蝎毒蛋白","slug":"claude-64小时设计出抗致命蝎毒蛋白","link":"#claude-64小时设计出抗致命蝎毒蛋白","children":[]},{"level":3,"title":"Anthropic估值砍5000亿 半年巨亏807亿","slug":"anthropic估值砍5000亿-半年巨亏807亿","link":"#anthropic估值砍5000亿-半年巨亏807亿","children":[]},{"level":3,"title":"陶哲轩邓煜呼吁数学「慢科研」","slug":"陶哲轩邓煜呼吁数学「慢科研」","link":"#陶哲轩邓煜呼吁数学「慢科研」","children":[]},{"level":3,"title":"Claude首次设计出抗蝎毒蛋白","slug":"claude首次设计出抗蝎毒蛋白","link":"#claude首次设计出抗蝎毒蛋白","children":[]},{"level":3,"title":"Meta叫停裁员，称还是人类好用","slug":"meta叫停裁员-称还是人类好用","link":"#meta叫停裁员-称还是人类好用","children":[]},{"level":3,"title":"OpenAI将COBOL迁移准确率提至97.9%","slug":"openai将cobol迁移准确率提至97-9","link":"#openai将cobol迁移准确率提至97-9","children":[]},{"level":3,"title":"奥特曼曝超级AI三大终局","slug":"奥特曼曝超级ai三大终局","link":"#奥特曼曝超级ai三大终局","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"清华团队用AI造世界最轻1克介观显微镜","slug":"清华团队用ai造世界最轻1克介观显微镜","link":"#清华团队用ai造世界最轻1克介观显微镜","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"2026年，我这样用AI知识库","slug":"_2026年-我这样用ai知识库","link":"#_2026年-我这样用ai知识库","children":[]},{"level":3,"title":"《2026AI原生基础设施白皮书》发布","slug":"《2026ai原生基础设施白皮书》发布","link":"#《2026ai原生基础设施白皮书》发布","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"1.3K Star开源项目抓AI热词快人一步","slug":"_1-3k-star开源项目抓ai热词快人一步","link":"#_1-3k-star开源项目抓ai热词快人一步","children":[]},{"level":3,"title":"DeepSeek开源DeepInfer推理框架","slug":"deepseek开源deepinfer推理框架","link":"#deepseek开源deepinfer推理框架","children":[]},{"level":3,"title":"DeepSeek推理利润率高达80%","slug":"deepseek推理利润率高达80","link":"#deepseek推理利润率高达80","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"RSIGame让AI自主开发超GPT-5.5","slug":"rsigame让ai自主开发超gpt-5-5","link":"#rsigame让ai自主开发超gpt-5-5","children":[]}]}],"git":{"updatedTime":1792918549000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"c141690054d39d6900bd2c5870bbc53443372c8b","time":1792918549000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-10-25T08:55:49.004Z"}]},"filePathRelative":"posts/2026-10-21.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-10-21 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>Claude 64小时设计出抗致命蝎毒蛋白</h3>\\n<p>Anthropic：Claude仅用64小时自主设计出抗致命蝎毒结合蛋白，湿实验验证17个设计成功达标，多靶点设计暂未突破，全部数据已开源，为AI药物研发开辟新方向。<a href=\\"https://mp.weixin.qq.com/s?__biz=Mzg3MTkxMjYzOA==&amp;chksm=cfe024aace30f87bafc2df6604bb23d78b9b09f7a7a20e9ff4cde177943442df8abbb802f718&amp;idx=2&amp;mid=2247519733&amp;sn=b924c295dc0734d7229a83f515e1b19d#rd\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{s as comp,l as data};
